<?php
declare(strict_types=1);
namespace OCA\JsonDashboard\Controller;
use OCA\JsonDashboard\AppInfo\Application; use OCP\AppFramework\Controller; use OCP\AppFramework\Http\DataResponse; use OCP\Http\Client\IClientService; use OCP\{IConfig,IRequest,IUserSession}; use Psr\Log\LoggerInterface; use Throwable;
final class DataController extends Controller { public function __construct(IRequest $request,private IClientService $clients,private IConfig $config,private IUserSession $users,private LoggerInterface $logger){parent::__construct(Application::APP_ID,$request);} public function read(int $slot):DataResponse{$uid=$this->users->getUser()?->getUID()??'';if($uid===''||$slot<1||$slot>Application::MAX_WIDGETS)return new DataResponse(['message'=>'Ungültiges Widget.'],400);$url=trim($this->config->getUserValue($uid,Application::APP_ID,'widget_'.$slot.'_url',''));$key=trim($this->config->getUserValue($uid,Application::APP_ID,'widget_'.$slot.'_key','Test'));if(filter_var($url,FILTER_VALIDATE_URL)===false||strtolower((string)parse_url($url,PHP_URL_SCHEME))!=='https')return new DataResponse(['message'=>'Ungültige HTTPS-Quelle.'],400);try{$r=$this->clients->newClient()->get($url,['timeout'=>10,'connect_timeout'=>5,'headers'=>['Accept'=>'application/json']]);if($r->getStatusCode()<200||$r->getStatusCode()>=300)throw new \RuntimeException('HTTP '.$r->getStatusCode());$json=json_decode($r->getBody(),true,512,JSON_THROW_ON_ERROR);$items=is_array($json[$key]??null)?array_values($json[$key]):[];return new DataResponse(['elements'=>$items]);}catch(Throwable $e){$this->logger->error('JSON dashboard load failed',['app'=>Application::APP_ID,'slot'=>$slot,'exception'=>$e]);return new DataResponse(['message'=>'JSON-Daten konnten nicht geladen werden.'],502);}} }
